1	/**
2	* @author Mark Kellogg - http://www.github.com/mkkellogg
3	*/
4	import * as THREE from 'three';
5	
6	//=======================================
7	// Trail Renderer
8	//=======================================
9	
10	export class TrailRenderer extends THREE.Object3D {
11	
12	    constructor (scene, orientToMovement) {
13	        super();
14	        this.active = false;
15	        this.orientToMovement = false;
16	        if (orientToMovement) this.orientToMovement = true;
17	        this.scene = scene;
18	        this.geometry = null;
19	        this.mesh = null;
20	        this.nodeCenters = null;
21	        this.lastNodeCenter = null;
22	        this.currentNodeCenter = null;
23	        this.lastOrientationDir = null;
24	        this.nodeIDs = null;
25	        this.currentLength = 0;
26	        this.currentEnd = 0;
27	        this.currentNodeID = 0;
28	        this.advanceFrequency = 60;
29	        this.advancePeriod = 1 / this.advanceFrequency;
30	        this.lastAdvanceTime = 0;
31	        this.paused = false;
32	        this.pauseAdvanceUpdateTimeDiff = 0;
33	    }
34	
35	    setAdvanceFrequency(advanceFrequency) {
36	        this.advanceFrequency = advanceFrequency;
37	        this.advancePeriod = 1.0 / this.advanceFrequency;
38	    }
39	
40	    initialize (material, length, dragTexture, localHeadWidth, localHeadGeometry, targetObject) {
41	        this.deactivate();
42	        this.destroyMesh();
43	
44	        this.length = (length > 0) ? length + 1 : 0;
45	        this.dragTexture = (! dragTexture) ? 0 : 1;
46	        this.targetObject = targetObject;
47	
48	        this.initializeLocalHeadGeometry(localHeadWidth, localHeadGeometry);
49	
50	        this.nodeIDs = [];
51	        this.nodeCenters = [];
52	
53	        for(let i = 0; i < this.length; i ++) {
54	            this.nodeIDs[ i ] = -1;
55	            this.nodeCenters[ i ] = new THREE.Vector3();
56	        }
57	
58	        this.material = material;
59	
60	        this.initializeGeometry();
61	        this.initializeMesh();
62	
63	        this.material.uniforms.trailLength.value = 0;
64	        this.material.uniforms.minID.value = 0;
65	        this.material.uniforms.maxID.value = 0;
66	        this.material.uniforms.dragTexture.value = this.dragTexture;
67	        this.material.uniforms.maxTrailLength.value = this.length;
68	        this.material.uniforms.verticesPerNode.value = this.VerticesPerNode;
69	        this.material.uniforms.textureTileFactor.value = new THREE.Vector2(1.0, 1.0);
70	
71	        this.reset();
72	    }
73	
74	    initializeLocalHeadGeometry (localHeadWidth, localHeadGeometry) {
75	        this.localHeadGeometry = [];
76	        if (!localHeadGeometry) {
77	            const halfWidth = (localHeadWidth || 1.0) / 2.0;
78	            this.localHeadGeometry.push(new THREE.Vector3(-halfWidth, 0, 0));
79	            this.localHeadGeometry.push(new THREE.Vector3(halfWidth, 0, 0));
80	            this.VerticesPerNode = 2;
81	        } else {
82	            this.VerticesPerNode = 0;
83	            for (let i = 0; i < localHeadGeometry.length && i < TrailRenderer.MaxHeadVertices; i++) {
84	                const vertex = localHeadGeometry[ i ];
85	                if (vertex && vertex instanceof THREE.Vector3) {
86	                    const vertexCopy = new THREE.Vector3();
87	                    vertexCopy.copy(vertex);
88	                    this.localHeadGeometry.push(vertexCopy);
89	                    this.VerticesPerNode ++;
90	                }
91	            }
92	        }
93	        this.FacesPerNode = (this.VerticesPerNode - 1) * 2;
94	        this.FaceIndicesPerNode = this.FacesPerNode * 3;
95	    }
96	
97	    initializeGeometry () {
98	        this.vertexCount = this.length * this.VerticesPerNode;
99	        this.faceCount = this.length * this.FacesPerNode;
100	
101	        const geometry = new THREE.BufferGeometry();
102	
103	        const nodeIDs = new Float32Array(this.vertexCount);
104	        const nodeVertexIDs = new Float32Array(this.vertexCount * this.VerticesPerNode);
105	        const positions = new Float32Array(this.vertexCount * TrailRenderer.PositionComponentCount);
106	        const nodeCenters = new Float32Array(this.vertexCount * TrailRenderer.PositionComponentCount);
107	        const uvs = new Float32Array(this.vertexCount * TrailRenderer.UVComponentCount);
108	        const indices = new Uint32Array(this.faceCount * TrailRenderer.IndicesPerFace);
109	
110	        const nodeIDAttribute = new THREE.BufferAttribute(nodeIDs, 1);
111	        nodeIDAttribute.dynamic = true;
112	        geometry.setAttribute('nodeID', nodeIDAttribute);
113	
114	        const nodeVertexIDAttribute = new THREE.BufferAttribute(nodeVertexIDs, 1);
115	        nodeVertexIDAttribute.dynamic = true;
116	        geometry.setAttribute('nodeVertexID', nodeVertexIDAttribute);
117	
118	        const nodeCenterAttribute = new THREE.BufferAttribute(nodeCenters, TrailRenderer.PositionComponentCount);
119	        nodeCenterAttribute.dynamic = true;
120	        geometry.setAttribute('nodeCenter', nodeCenterAttribute);
121	
122	        const positionAttribute = new THREE.BufferAttribute(positions, TrailRenderer.PositionComponentCount);
123	        positionAttribute.dynamic = true;
124	        geometry.setAttribute('position', positionAttribute);
125	
126	        const uvAttribute = new THREE.BufferAttribute(uvs, TrailRenderer.UVComponentCount);
127	        uvAttribute.dynamic = true;
128	        geometry.setAttribute('uv', uvAttribute);
129	
130	        const indexAttribute = new THREE.BufferAttribute(indices, 1);
131	        indexAttribute.dynamic = true;
132	        geometry.setIndex(indexAttribute);
133	
134	        this.geometry = geometry;
135	    }
136	
137	    zeroVertices () {
138	        const positions = this.geometry.getAttribute('position');
139	        for (let i = 0; i < this.vertexCount; i ++) {
140	            const index = i * 3;
141	            positions.array[ index ] = 0;
142	            positions.array[ index + 1 ] = 0;
143	            positions.array[ index + 2 ] = 0;
144	        }
145	        positions.needsUpdate = true;
146	        positions.updateRange.count = - 1;
147	    }
148	
149	    zeroIndices () {
150	        const indices = this.geometry.getIndex();
151	        for (let i = 0; i < this.faceCount; i ++) {
152	            const index = i * 3;
153	            indices.array[ index ] = 0;
154	            indices.array[ index + 1 ] = 0;
155	            indices.array[ index + 2 ] = 0;
156	        }
157	        indices.needsUpdate = true;
158	        indices.updateRange.count = - 1;
159	    }
160	
161	    formInitialFaces () {
162	        this.zeroIndices();
163	        const indices = this.geometry.getIndex();
164	        for (let i = 0; i < this.length - 1; i ++) {
165	            this.connectNodes(i, i + 1);
166	        }
167	        indices.needsUpdate = true;
168	        indices.updateRange.count = - 1;
169	    }
170	
171	    initializeMesh () {
172	        this.mesh = new THREE.Mesh(this.geometry, this.material);
173	        this.mesh.dynamic = true;
174	        this.mesh.matrixAutoUpdate = false;
175	    }
176	
177	    destroyMesh () {
178	        if (this.mesh) {
179	            this.scene.remove(this.mesh);
180	            this.mesh = null;
181	        }
182	    }
183	
184	    reset () {
185	        this.currentLength = 0;
186	        this.currentEnd = -1;
187	        this.lastNodeCenter = null;
188	        this.currentNodeCenter = null;
189	        this.lastOrientationDir = null;
190	        this.currentNodeID = 0;
191	        this.formInitialFaces();
192	        this.zeroVertices();
193	        this.geometry.setDrawRange(0, 0);
194	    }
195	
196	    updateUniforms () {
197	        if (this.currentLength < this.length) {
198	            this.material.uniforms.minID.value = 0;
199	        } else {
200	            this.material.uniforms.minID.value = this.currentNodeID - this.length;
201	        }
202	        this.material.uniforms.maxID.value = this.currentNodeID;
203	        this.material.uniforms.trailLength.value = this.currentLength;
204	        this.material.uniforms.maxTrailLength.value = this.length;
205	        this.material.uniforms.verticesPerNode.value = this.VerticesPerNode;
206	    }
207	
208	    advance = function() {
209	        const tempMatrix4 = new THREE.Matrix4();
210	        return function advance() {
211	            this.targetObject.updateMatrixWorld();
212	            tempMatrix4.copy(this.targetObject.matrixWorld);
213	            this.advanceWithTransform(tempMatrix4);
214	            this.updateUniforms();
215	        };
216	    }();
217	
218	    advanceWithPositionAndOrientation (nextPosition, orientationTangent) {
219	        this.advanceGeometry({ position : nextPosition, tangent : orientationTangent }, null);
220	    }
221	
222	    advanceWithTransform (transformMatrix) {
223	        this.advanceGeometry(null, transformMatrix);
224	    }
225	
226	    advanceGeometry = function() { 
227	
228	        return function advanceGeometry(positionAndOrientation, transformMatrix) {
229	            const nextIndex = this.currentEnd + 1 >= this.length ? 0 : this.currentEnd + 1; 
230	            if(transformMatrix) {
231	                this.updateNodePositionsFromTransformMatrix(nextIndex, transformMatrix);
232	            } else {
233	                this.updateNodePositionsFromOrientationTangent(nextIndex, positionAndOrientation.position, positionAndOrientation.tangent);
234	            }
235	
236	            if (this.currentLength >= 1) {
237	                this.connectNodes(this.currentEnd , nextIndex);
238	                if(this.currentLength >= this.length) {
239	                    const disconnectIndex  = this.currentEnd + 1  >= this.length ? 0 : this.currentEnd + 1;
240	                    this.disconnectNodes(disconnectIndex);
241	                }
242	            }
243	
244	            if(this.currentLength < this.length) {
245	                this.currentLength ++;
246	            }
247	
248	            this.currentEnd++;
249	            if (this.currentEnd >= this.length) {
250	                this.currentEnd = 0;
251	            }
252	
253	            if (this.currentLength >= 1) {
254	                if(this.currentLength < this.length) {
255	                    this.geometry.setDrawRange(0, (this.currentLength - 1) * this.FaceIndicesPerNode);
256	                } else {
257	                    this.geometry.setDrawRange(0, this.currentLength * this.FaceIndicesPerNode);
258	                }
259	            }
260	            this.updateNodeID(this.currentEnd,  this.currentNodeID);
261	            this.currentNodeID ++;
262	        };
263	
264	    }();
265	
266	    currentTime() {
267	        return performance.now() / 1000;
268	    }
269	
270	    pause() {
271	        if(!this.paused) {
272	            this.paused = true;
273	            this.pauseAdvanceUpdateTimeDiff = this.currentTime() - this.lastAdvanceTime;
274	        }
275	    }
276	
277	    resume() {
278	        if(this.paused) {
279	            this.paused = false;
280	            this.lastAdvanceTime = this.currentTime() - this.pauseAdvanceUpdateTimeDiff;
281	        }
282	    }
283	
284	    update() {
285	        if (!this.paused) {
286	            const time = this.currentTime();
287	            if (!this.lastAdvanceTime) this.lastAdvanceTime = time;
288	            if (time - this.lastAdvanceTime > this.advancePeriod) {
289	                this.advance();
290	                this.lastAdvanceTime = time;
291	            } else {
292	                this.updateHead();
293	            }
294	        }
295	    }
296	
297	    updateHead = function() {
298	
299	        const tempMatrix4 = new THREE.Matrix4();
300	
301	        return function updateHead() {
302	            if(this.currentEnd < 0) return;
303	            this.targetObject.updateMatrixWorld();
304	            tempMatrix4.copy(this.targetObject.matrixWorld);
305	            this.updateNodePositionsFromTransformMatrix(this.currentEnd, tempMatrix4);
306	        };
307	
308	    }();
309	
310	    updateNodeID (nodeIndex, id) { 
311	        this.nodeIDs[ nodeIndex ] = id;
312	        const nodeIDs = this.geometry.getAttribute('nodeID');
313	        const nodeVertexIDs = this.geometry.getAttribute('nodeVertexID');
314	        for (let i = 0; i < this.VerticesPerNode; i ++) {
315	            const baseIndex = nodeIndex * this.VerticesPerNode + i ;
316	            nodeIDs.array[ baseIndex ] = id;
317	            nodeVertexIDs.array[ baseIndex ] = i;
318	        }    
319	        nodeIDs.needsUpdate = true;
320	        nodeVertexIDs.needsUpdate = true;
321	        nodeIDs.updateRange.offset = nodeIndex * this.VerticesPerNode; 
322	        nodeIDs.updateRange.count = this.VerticesPerNode;
323	        nodeVertexIDs.updateRange.offset = nodeIndex * this.VerticesPerNode;
324	        nodeVertexIDs.updateRange.count = this.VerticesPerNode;
325	    }
326	
327	    updateNodeCenter (nodeIndex, nodeCenter) { 
328	        this.lastNodeCenter = this.currentNodeCenter;
329	        this.currentNodeCenter = this.nodeCenters[ nodeIndex ];
330	        this.currentNodeCenter.copy(nodeCenter);
331	        const nodeCenters = this.geometry.getAttribute('nodeCenter');
332	        for (let i = 0; i < this.VerticesPerNode; i ++) {
333	            const baseIndex = (nodeIndex * this.VerticesPerNode + i) * 3;
334	            nodeCenters.array[ baseIndex ] = nodeCenter.x;
335	            nodeCenters.array[ baseIndex + 1 ] = nodeCenter.y;
336	            nodeCenters.array[ baseIndex + 2 ] = nodeCenter.z;
337	        }    
338	        nodeCenters.needsUpdate = true;
339	        nodeCenters.updateRange.offset = nodeIndex * this.VerticesPerNode * TrailRenderer.PositionComponentCount; 
340	        nodeCenters.updateRange.count = this.VerticesPerNode * TrailRenderer.PositionComponentCount; 
341	    }
342	
343	    updateNodePositionsFromOrientationTangent = function() { 
344	
345	        const tempQuaternion = new THREE.Quaternion();
346	        const tempOffset = new THREE.Vector3();
347	        const tempLocalHeadGeometry = [];
348	        for (let i = 0; i < TrailRenderer.MaxHeadVertices; i ++) {
349	            const vertex = new THREE.Vector3();
350	            tempLocalHeadGeometry.push(vertex);
351	        }
352	
353	        return function updateNodePositionsFromOrientationTangent(nodeIndex, nodeCenter, orientationTangent ) {
354	            const positions = this.geometry.getAttribute('position');
355	            this.updateNodeCenter(nodeIndex, nodeCenter);
356	            tempOffset.copy(nodeCenter);
357	            tempOffset.sub(TrailRenderer.LocalHeadOrigin);
358	            tempQuaternion.setFromUnitVectors(TrailRenderer.LocalOrientationTangent, orientationTangent);
359	
360	            for (let i = 0; i < this.localHeadGeometry.length; i ++) {
361	                const vertex = tempLocalHeadGeometry[ i ];
362	                vertex.copy(this.localHeadGeometry[ i ]);
363	                vertex.applyQuaternion(tempQuaternion);
364	                vertex.add(tempOffset);
365	            }
366	
367	            for (let i = 0; i <  this.localHeadGeometry.length; i ++) {
368	                const positionIndex = ((this.VerticesPerNode * nodeIndex) + i) * TrailRenderer.PositionComponentCount;
369	                const transformedHeadVertex = tempLocalHeadGeometry[ i ];
370	                positions.array[ positionIndex ] = transformedHeadVertex.x;
371	                positions.array[ positionIndex + 1 ] = transformedHeadVertex.y;
372	                positions.array[ positionIndex + 2 ] = transformedHeadVertex.z;
373	            }
374	
375	            positions.needsUpdate = true;
376	        };
377	
378	    }();
379	
380	    updateNodePositionsFromTransformMatrix = function() { 
381	
382	        const tempMatrix3 = new THREE.Matrix3();
383	        const tempQuaternion = new THREE.Quaternion();
384	        const tempPosition = new THREE.Vector3();
385	        const tempOffset = new THREE.Vector3();
386	        const worldOrientation = new THREE.Vector3();
387	        const tempDirection = new THREE.Vector3();
388	
389	        const tempLocalHeadGeometry = [];
390	        for (let i = 0; i < TrailRenderer.MaxHeadVertices; i ++) {
391	            const vertex = new THREE.Vector3();
392	            tempLocalHeadGeometry.push(vertex);
393	        }
394	
395	        function getMatrix3FromMatrix4(matrix3, matrix4) {
396	            const e = matrix4.elements;
397	            matrix3.set(e[0], e[1], e[2],
398	                        e[4], e[5], e[6],
399	                        e[8], e[9], e[10]);
400	
401	        }
402	
403	        return function updateNodePositionsFromTransformMatrix(nodeIndex, transformMatrix) {
404	            const positions = this.geometry.getAttribute('position');
405	            tempPosition.set(0, 0, 0);
406	            tempPosition.applyMatrix4(transformMatrix);
407	            this.updateNodeCenter(nodeIndex, tempPosition);
408	            for (let i = 0; i < this.localHeadGeometry.length; i ++) {
409	                const vertex = tempLocalHeadGeometry[ i ];
410	                vertex.copy(this.localHeadGeometry[ i ]);
411	            }
412	
413	            for (let i = 0; i < this.localHeadGeometry.length; i ++) {
414	                const vertex = tempLocalHeadGeometry[ i ];
415	                vertex.applyMatrix4(transformMatrix);
416	            }
417	            
418	            if(this.lastNodeCenter && this.orientToMovement) {
419	                getMatrix3FromMatrix4(tempMatrix3, transformMatrix);
420	                worldOrientation.set(0, 0, -1);
421	                worldOrientation.applyMatrix3(tempMatrix3);
422	                tempDirection.copy(this.currentNodeCenter);
423	                tempDirection.sub(this.lastNodeCenter);
424	                tempDirection.normalize();
425	
426	                if(tempDirection.lengthSq() <= .0001 && this.lastOrientationDir) {
427	                    tempDirection.copy(this.lastOrientationDir);
428	                }
429	
430	                if(tempDirection.lengthSq() > .0001) {
431	                    if(! this.lastOrientationDir) this.lastOrientationDir = new THREE.Vector3();
432	                    tempQuaternion.setFromUnitVectors(worldOrientation, tempDirection);
433	                    tempOffset.copy(this.currentNodeCenter);
434	                    for (let i = 0; i < this.localHeadGeometry.length; i ++) {
435	                        const vertex = tempLocalHeadGeometry[ i ];
436	                        vertex.sub(tempOffset);
437	                        vertex.applyQuaternion(tempQuaternion);
438	                        vertex.add(tempOffset);
439	                    }
440	                }
441	            }
442	
443	            for (let i = 0; i < this.localHeadGeometry.length; i ++) {
444	                const positionIndex = ((this.VerticesPerNode * nodeIndex) + i) * TrailRenderer.PositionComponentCount;
445	                const transformedHeadVertex = tempLocalHeadGeometry[ i ];
446	                positions.array[ positionIndex ] = transformedHeadVertex.x;
447	                positions.array[ positionIndex + 1 ] = transformedHeadVertex.y;
448	                positions.array[ positionIndex + 2 ] = transformedHeadVertex.z;
449	            }
450	            positions.needsUpdate = true;
451	            positions.updateRange.offset = nodeIndex * this.VerticesPerNode * TrailRenderer.PositionComponentCount; 
452	            positions.updateRange.count = this.VerticesPerNode * TrailRenderer.PositionComponentCount; 
453	        };
454	
455	    }();
456	
457	    connectNodes = function() {
458	
459	        const returnObj = {
460	            "attribute" : null,
461	            "offset" : 0,
462	            "count" : - 1
463	        };
464	
465	        return function connectNodes(srcNodeIndex, destNodeIndex) {
466	            const indices = this.geometry.getIndex();
467	            for (let i = 0; i < this.localHeadGeometry.length - 1; i ++) {
468	                const srcVertexIndex = (this.VerticesPerNode * srcNodeIndex) + i;
469	                const destVertexIndex = (this.VerticesPerNode * destNodeIndex) + i;
470	                const faceIndex = ((srcNodeIndex * this.FacesPerNode) + (i * TrailRenderer.FacesPerQuad )) * TrailRenderer.IndicesPerFace;
471	                indices.array[ faceIndex ] = srcVertexIndex;
472	                indices.array[ faceIndex + 1 ] = destVertexIndex;
473	                indices.array[ faceIndex + 2 ] = srcVertexIndex + 1;
474	                indices.array[ faceIndex + 3 ] = destVertexIndex;
475	                indices.array[ faceIndex + 4 ] = destVertexIndex + 1;
476	                indices.array[ faceIndex + 5 ] = srcVertexIndex + 1;
477	            }
478	            indices.needsUpdate = true;
479	            indices.updateRange.count = - 1;
480	            returnObj.attribute = indices;
481	            returnObj.offset =  srcNodeIndex * this.FacesPerNode * TrailRenderer.IndicesPerFace;
482	            returnObj.count = this.FacesPerNode * TrailRenderer.IndicesPerFace;
483	            return returnObj;
484	
485	        };
486	
487	    }();
488	
489	    disconnectNodes = function() {
490	
491	        const returnObj = {
492	            "attribute" : null,
493	            "offset" : 0,
494	            "count" : - 1
495	        };
496	
497	        return function disconnectNodes(srcNodeIndex) {
498	            const indices = this.geometry.getIndex();
499	            for (let i = 0; i < this.localHeadGeometry.length - 1; i ++) {
500	                const faceIndex = ((srcNodeIndex * this.FacesPerNode) + (i * TrailRenderer.FacesPerQuad)) * TrailRenderer.IndicesPerFace;
501	                indices.array[ faceIndex ] = 0;
502	                indices.array[ faceIndex + 1 ] = 0;
503	                indices.array[ faceIndex + 2 ] = 0;
504	                indices.array[ faceIndex + 3 ] = 0;
505	                indices.array[ faceIndex + 4 ] = 0;
506	                indices.array[ faceIndex + 5 ] = 0;
507	            }
508	            indices.needsUpdate = true;
509	            indices.updateRange.count = - 1;
510	            returnObj.attribute = indices;
511	            returnObj.offset = srcNodeIndex * this.FacesPerNode * TrailRenderer.IndicesPerFace;
512	            returnObj.count = this.FacesPerNode * TrailRenderer.IndicesPerFace;
513	            return returnObj;
514	        };
515	
516	    }();
517	
518	    deactivate () {
519	        if (this.isActive) {
520	            this.scene.remove(this.mesh);
521	            this.isActive = false;
522	        }
523	    }
524	
525	    activate () {
526	        if (! this.isActive) {
527	            this.scene.add(this.mesh);
528	            this.isActive = true;
529	        }
530	    }
531	
532	    static createMaterial(vertexShader, fragmentShader, customUniforms) {
533	
534	        customUniforms = customUniforms || {};
535	        customUniforms.trailLength = { type: "f", value: null };
536	        customUniforms.verticesPerNode = { type: "f", value: null };
537	        customUniforms.minID = { type: "f", value: null };
538	        customUniforms.maxID = { type: "f", value: null };
539	        customUniforms.dragTexture = { type: "f", value: null };
540	        customUniforms.maxTrailLength = { type: "f", value: null };
541	        customUniforms.textureTileFactor = { type: "v2", value: null };
542	        customUniforms.headColor = { type: "v4", value: new THREE.Vector4() };
543	        customUniforms.tailColor = { type: "v4", value: new THREE.Vector4() };
544	
545	        vertexShader = vertexShader || TrailRenderer.Shader.BaseVertexShader;
546	        fragmentShader = fragmentShader || TrailRenderer.Shader.BaseFragmentShader;
547	
548	        return new THREE.ShaderMaterial({
549	            uniforms: customUniforms,
550	            vertexShader: vertexShader,
551	            fragmentShader: fragmentShader,
552	            transparent: true,
553	            alphaTest: 0.5,
554	            blending : THREE.CustomBlending,
555	            blendSrc : THREE.SrcAlphaFactor,
556	            blendDst : THREE.OneMinusSrcAlphaFactor,
557	            blendEquation : THREE.AddEquation,
558	            depthTest: true,
559	            depthWrite: false,
560	            side: THREE.DoubleSide
561	        });
562	    
563	    }
564	    
565	    static createBaseMaterial(customUniforms) {
566	        return TrailRenderer.createMaterial(TrailRenderer.Shader.BaseVertexShader, TrailRenderer.Shader.BaseFragmentShader, customUniforms);
567	    }
568	
569	    static createTexturedMaterial (customUniforms) {
570	        customUniforms = {};
571	        customUniforms.trailTexture = { type: "t", value: null };
572	        return TrailRenderer.createMaterial(TrailRenderer.Shader.TexturedVertexShader, TrailRenderer.Shader.TexturedFragmentShader, customUniforms);
573	    }
574	
575	    static get MaxHeadVertices () {
576	        return 128;
577	    }
578	
579	    static _LocalOrientationTangent = new THREE.Vector3(1, 0, 0);
580	    static get LocalOrientationTangent () {
581	        return _LocalOrientationTangent;
582	    }
583	
584	    static _LocalHeadOrigin = new THREE.Vector3(0, 0, 0);
585	    static get LocalHeadOrigin () {
586	        return _LocalHeadOrigin;
587	    }
588	
589	    static get PositionComponentCount () {
590	        return 3;
591	    }
592	
593	    static get UVComponentCount () {
594	        return 2;
595	    }
596	
597	    static get IndicesPerFace () {
598	        return 3;
599	    }
600	
601	    static get FacesPerQuad () {
602	        return 2;
603	    }
604	
605	    static Shader = {
606	
607	        get BaseVertexVars() {
608	            return [
609	                "attribute float nodeID;",
610	                "attribute float nodeVertexID;",
611	                "attribute vec3 nodeCenter;",
612	                "uniform float minID;",
613	                "uniform float maxID;",
614	                "uniform float trailLength;",
615	                "uniform float maxTrailLength;",
616	                "uniform float verticesPerNode;",
617	                "uniform vec2 textureTileFactor;",
618	                "uniform vec4 headColor;",
619	                "uniform vec4 tailColor;",
620	                "varying vec4 vColor;",
621	            ].join("\n")
622	        },
623	
624	        get TexturedVertexVars() {
625	            return [
626	                this.BaseVertexVars, 
627	                "varying vec2 vUV;",
628	                "uniform float dragTexture;",
629	            ].join("\n");
630	        },
