645	            return [
646	                "float fraction = (maxID - nodeID) / (maxID - minID);",
647	                "vColor = (1.0 - fraction) * headColor + fraction * tailColor;",
648	                "vec4 realPosition = vec4((1.0 - fraction) * position.xyz + fraction * nodeCenter.xyz, 1.0); ", 
649	            ].join("\n");
650	        },
651	
652	        get BaseVertexShader() {
653	            return [
654	                this.BaseVertexVars,
655	                "void main() { ",
656	                    this.VertexShaderCore,
657	                    "gl_Position = projectionMatrix * viewMatrix * realPosition;",
658	                "}"
659	            ].join("\n");
660	        },
661	
662	        get BaseFragmentShader() {
