674	                "void main() { ",
675	                    this.VertexShaderCore,
676	                    "float s = 0.0;",
677	                    "float t = 0.0;",
678	                    "if (dragTexture == 1.0) { ",
679	                    "   s = fraction *  textureTileFactor.s; ",
680	                    "     t = (nodeVertexID / verticesPerNode) * textureTileFactor.t;",
681	                    "} else { ",
